if(!(isset($_SESSION['ACCESSLEVEL'],$_SESSION['SYSTEMTYPE'])&&$_SESSION['ACCESSLEVEL']==='user'&&$_SESSION['SYSTEMTYPE']==='Student'))exit('Student login required.');$uid=mysqli_real_escape_string($con,$_SESSION['USERID']);$ids=isset($_POST['billids'])&&is_array($_POST['billids'])?$_POST['billids']:array();$requested=isset($_POST['amounts'])&&is_array($_POST['amounts'])?$_POST['amounts']:array();if(empty($ids))exit('Select at least one bill.');$safe=array();foreach($ids as $id){$id=trim((string)$id);if($id!=='')$safe[]="'".mysqli_real_escape_string($con,$id)."'";}if(empty($safe))exit('Invalid bill selection.');$r=mysqli_query($con,"SELECT bi.billid,bi.cost-COALESCE(SUM(pm.payment),0) balance FROM tblbilling bi LEFT JOIN tblpayment pm ON pm.billid=bi.billid AND pm.status='active' WHERE bi.userid='$uid' AND bi.billid IN (".implode(',',$safe).") GROUP BY bi.billid,bi.cost HAVING balance>0.009");$bills=array();$total=0;while($r&&($row=mysqli_fetch_assoc($r))){$want=isset($requested[$row['billid']])?(float)$requested[$row['billid']]:0;if($want<=0||$want>(float)$row['balance']+0.001)exit('Each selected amount must be greater than zero and no more than its outstanding balance.');$row['amount']=$want;$bills[]=$row;$total+=$want;}if(empty($bills))exit('No selected bills have a valid outstanding balance.');$u=mysqli_query($con,"SELECT email FROM tblsystemuser WHERE userid='$uid' LIMIT 1");$ur=$u?mysqli_fetch_assoc($u):null;$email=isset($ur['email'])?$ur['email']:'';if(!filter_var($email,FILTER_VALIDATE_EMAIL))exit('A valid email address is required to pay online.');@mysqli_query($con,"CREATE TABLE IF NOT EXISTS tblstudentonlinepayment(referenceid VARCHAR(120) PRIMARY KEY,userid VARCHAR(100) NOT NULL,amount DECIMAL(12,2) NOT NULL,status VARCHAR(20) NOT NULL,createdat DATETIME NOT NULL,paidat DATETIME NULL)");@mysqli_query($con,"CREATE TABLE IF NOT EXISTS tblstudentonlinepaymentbill(referenceid VARCHAR(120) NOT NULL,billid VARCHAR(100) NOT NULL,amount DECIMAL(12,2) NOT NULL,PRI